t("liste de tous les salons", req("GET", "v7/lobbies", A), 401)
t("secret écrit avant le salon", req("PUT", "v7/secrets/1234", A, "abc123"), 200)
t("lecture du secret interdite", req("GET", "v7/secrets/1234", Bt), 401)
