t("piégé : lire tous les mots d'un coup", req("GET", "v7/pieges/5678/p42", C), 401)
t("piégé : réécrire un mot déjà choisi", req("PUT", f"v7/pieges/5678/p42/{ub}", A, {"mot": "TOMATE", "de": ua}), 401)
t("piégé : écrire son propre mot", req("PUT", f"v7/pieges/5678/p42/{uc}", C, {"mot": "TOMATE", "de": uc}), 401)
t("piégé : écrire le mot d'une cible qui n'est pas la sienne (avant la fin du choix)", req("PUT", f"v7/pieges/5678/p42/{uc}", A, {"mot": "TOMATE", "de": ua}), 401)
t("piégé : mot avec chiffre ou minuscule", req("PUT", f"v7/pieges/5678/p42/{uc}", Bt, {"mot": "Pat4te", "de": ub}), 401)
t("piégé : mot trop court pour les réglages", req("PUT", f"v7/pieges/5678/p42/{uc}", Bt, {"mot": "CHAT", "de": ub}), 401)
