t("piégé : champ inconnu dans le mot", req("PUT", f"v7/pieges/5678/p42/{uc}", Bt, {"mot": "TOMATE", "de": ub, "indice": "rouge"}), 401)
t("piégé : mot valide du choisisseur", req("PUT", f"v7/pieges/5678/p42/{uc}", Bt, {"mot": "TOMATE", "de": ub}), 200)
t("piégé : mot de secours avant la fin du choix", req("PUT", f"v7/pieges/5678/p42/{ua}", Bt, {"mot": "CAROTTE", "de": uc, "auto": True}), 401)
t("piégé : l'hôte avance la fin du choix", req("PATCH", "v7/lobbies/5678/settings", A, {"piege_fin_choix": int(time.time() * 1000) - 1000}), 200)
t("piégé : la cible ne peut pas s'attribuer un mot de secours", req("PUT", f"v7/pieges/5678/p42/{ua}", A, {"mot": "CAROTTE", "de": uc, "auto": True}), 401)
t("piégé : mot de secours après la fin du choix", req("PUT", f"v7/pieges/5678/p42/{ua}", Bt, {"mot": "CAROTTE", "de": uc, "auto": True}), 200)
t("piégé : annonce du mot prêt par la cible elle-même", req("PUT", f"v7/lobbies/5678/piege_pret/{ub}", Bt, {"n": 6, "p": "P"}), 401)
t("piégé : annonce du mot prêt par le choisisseur", req("PUT", f"v7/lobbies/5678/piege_pret/{ub}", A, {"n": 6, "p": "P"}), 200)
t("piégé : la cible propose un mot", req("PUT", f"v7/lobbies/5678/piege_essais/{ub}/e0", Bt, "PATOTE"), 200)
